    links: [{ label: "HKU Li Ka Shing Faculty of Medicine", url: "https://www.med.hku.hk" }, { label: "HKU Clinical Trials Centre", url: "https://www.hkuctc.com" }, { label: "Hospital Authority: Queen Mary Hospital", url: "https://www.ha.org.hk" }],
